#include "oneblock_plan.hpp"
#include <iostream>
using namespace zkgpt::r7;using namespace oneblock;
int main(){try{zkgpt::r1::init();auto p=discover();requireCoverage(p);auto changed=p;changed.required.pop_back();crypto::need(identity(changed)!=identity(p),"omitted native relation must change coverage identity");auto other=p;other.required.front().id+="/replacement";crypto::need(identity(other)!=identity(p),"replacement must change coverage identity");auto duplicate=p;duplicate.required.push_back(duplicate.required.front());bool rejected=false;try{requireCoverage(duplicate);}catch(...){rejected=true;}crypto::need(rejected,"duplicate relation rejected");std::size_t matrices=0,terminals=0;for(auto&r:p.required){matrices+=r.family=="FC_MATRIX";terminals+=r.family=="GKR_MASTER_TERMINAL";}crypto::need(matrices==2*p.fc_layers && terminals==p.native_terminals,"native FC/terminal coverage");crypto::need(p.objects.size()==p.source_objects && !p.required.empty(),"all native objects retained");std::cout<<"ONEBLOCK_PLAN_TESTED relations="<<p.required.size()<<" objects="<<p.objects.size()<<" terminals="<<terminals<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
